-- Migration: 20260724000002_qs_reseed_price_list_libraries.sql
-- Purpose: Refresh qs_element_library / qs_description_library reference data to match
--          docs/03-Business-Modules/12-Quantity-Surveying/Price List Libraries.xlsx
--          (Element Library, Description Library, Price List Library, Naming Standard
--          sheets), replacing the rough/incomplete rates from the earlier
--          20260723000002_qs_description_library_fill_costs.sql seed. Data-only change --
--          no application code, no schema changes. The existing "Pull from Element
--          Library" button/dialog/service (tender-cost-service.ts) are untouched; only the
--          reference data they read from is refreshed.
-- Depends on: public.qs_element_library (20260722000009), public.qs_description_library
--             (20260722000011, altered by 20260724000001), public.budget_codes
--             (20260711000003/20260711000004), public.tender_register
--             (20260723000003_tender_register_default_margins.sql)
--
-- Source row counts parsed from the workbook: Element Library 518 rows,
-- Description Library 803 rows, Price List Library 432 rows.
--
-- Data-quality note: source Description Library / Price List Library rows No.802/803
-- (PL-423/PL-424) -- "Toilet Floor tile" / "Toilet Wall tile" -- had Sub Section wrongly
-- duplicated from Sub Element instead of the real trade package name ("Floor tiling" /
-- "Wall tiling") used by the corresponding Element Library row (No.297/No.288). This was
-- corrected during parsing (not a Naming Standard sheet item) so these 2 rows attach to
-- their correct qs_element_library row in Phase C/D instead of being silently dropped.
--
-- Verified before generating this file: zero distinct Budget Codes in the Element Library
-- sheet are missing from public.budget_codes; zero (section, sub_section, sub_element)
-- triples span more than one Discipline; zero exact-duplicate hierarchy rows within each
-- sheet.

BEGIN;

-- ============================================================================
-- Phase A: Naming Standard renames (see 'Naming Standard' sheet, sheet 8, in
-- 'Price List Libraries.xlsx'). UPDATE-in-place only -- qs_description_library
-- .element_library_id has a real FK to qs_element_library, so rows are never
-- deleted/recreated here. Every rename is guarded with NOT EXISTS against the
-- target combination so it can never violate the
-- (discipline, section, sub_section, sub_element) UNIQUE constraint.
--
-- As of this migration's authoring, none of these 7 variant spellings exist in
-- the DB (confirmed by grep of the current seed migrations) -- these are
-- defensive no-ops that only take effect if the DB state ever drifts from what
-- was checked. The 8th item (generic trailing-whitespace trim) is applied as
-- an unconditional cleanup pass at the end of this phase.
-- ============================================================================

-- 1. "Interior Wall Finishes" (standard) vs "Internal Wall Finishes" (variant) -- Budget Code D.01
update public.qs_element_library t
set section = 'Interior Wall Finishes', updated_at = now()
where section = 'Internal Wall Finishes'
  and not exists (
    select 1 from public.qs_element_library e2
    where e2.discipline = t.discipline
      and e2.section = 'Interior Wall Finishes'
      and e2.sub_section = t.sub_section
      and e2.sub_element = t.sub_element
  );

-- 2. "Interior Floor Finishes" (standard) vs "Internal Floor Finishes" (variant) -- Budget Code D.02
update public.qs_element_library t
set section = 'Interior Floor Finishes', updated_at = now()
where section = 'Internal Floor Finishes'
  and not exists (
    select 1 from public.qs_element_library e2
    where e2.discipline = t.discipline
      and e2.section = 'Interior Floor Finishes'
      and e2.sub_section = t.sub_section
      and e2.sub_element = t.sub_element
  );

-- 3. "Ceiling Finishes" (standard) vs "Ceiling Finshes" (typo variant) -- Budget Code D.03
update public.qs_element_library t
set section = 'Ceiling Finishes', updated_at = now()
where section = 'Ceiling Finshes'
  and not exists (
    select 1 from public.qs_element_library e2
    where e2.discipline = t.discipline
      and e2.section = 'Ceiling Finishes'
      and e2.sub_section = t.sub_section
      and e2.sub_element = t.sub_element
  );

-- 4. "Exterior Wall and Partition" (standard) vs "External Wall and Partition" (variant) -- Budget Code C.01
update public.qs_element_library t
set section = 'Exterior Wall and Partition', updated_at = now()
where section = 'External Wall and Partition'
  and not exists (
    select 1 from public.qs_element_library e2
    where e2.discipline = t.discipline
      and e2.section = 'Exterior Wall and Partition'
      and e2.sub_section = t.sub_section
      and e2.sub_element = t.sub_element
  );

-- 5. "Exterior Window and Louver" (standard) vs "External Windows and Louvers" (variant) -- Budget Code C.04
update public.qs_element_library t
set section = 'Exterior Window and Louver', updated_at = now()
where section = 'External Windows and Louvers'
  and not exists (
    select 1 from public.qs_element_library e2
    where e2.discipline = t.discipline
      and e2.section = 'Exterior Window and Louver'
      and e2.sub_section = t.sub_section
      and e2.sub_element = t.sub_element
  );

-- 6. "Interior Doors" (standard) vs "Interior Door" (variant) -- Budget Code C.10
update public.qs_element_library t
set section = 'Interior Doors', updated_at = now()
where section = 'Interior Door'
  and not exists (
    select 1 from public.qs_element_library e2
    where e2.discipline = t.discipline
      and e2.section = 'Interior Doors'
      and e2.sub_section = t.sub_section
      and e2.sub_element = t.sub_element
  );

-- 7. "Handrail" (standard Sub Section) vs "Handrail on staircase" wrongly used as a
--    Sub Section (variant -- location should live in Sub Element/Description instead).
--    Current DB already stores this correctly as sub_section='Handrail',
--    sub_element='Handrail on staircase', so this is a no-op guard only.
update public.qs_element_library t
set sub_section = 'Handrail', updated_at = now()
where sub_section = 'Handrail on staircase'
  and not exists (
    select 1 from public.qs_element_library e2
    where e2.discipline = t.discipline
      and e2.section = t.section
      and e2.sub_section = 'Handrail'
      and e2.sub_element = t.sub_element
  );

-- 8. Generic trailing/leading-whitespace trim across all hierarchy fields
--    (e.g. "Formwork ", "Marble on staircase " noted in the Naming Standard sheet).
--    Guarded the same way to avoid tripping the UNIQUE constraint.
update public.qs_element_library t
set discipline  = btrim(discipline),
    section     = btrim(section),
    sub_section = btrim(sub_section),
    sub_element = btrim(sub_element),
    updated_at  = now()
where (discipline  <> btrim(discipline)
    or section     <> btrim(section)
    or sub_section <> btrim(sub_section)
    or sub_element <> btrim(sub_element))
  and not exists (
    select 1 from public.qs_element_library e2
    where e2.id <> t.id
      and e2.discipline  = btrim(t.discipline)
      and e2.section     = btrim(t.section)
      and e2.sub_section = btrim(t.sub_section)
      and e2.sub_element = btrim(t.sub_element)
  );

update public.qs_description_library t
set description = btrim(description), updated_at = now()
where description <> btrim(description)
  and not exists (
    select 1 from public.qs_description_library d2
    where d2.id <> t.id
      and d2.element_library_id = t.element_library_id
      and d2.description = btrim(t.description)
  );

