-- ============================================================================
-- Phase E: NOTE -- this reseed is additive/corrective, not exhaustive. No
-- qs_element_library or qs_description_library row that has no counterpart in
-- 'Price List Libraries.xlsx' is deleted or deactivated here. Rows already in
-- the DB (from the earlier QS_Element_Library.xlsx seed) that this workbook
-- doesn't happen to mention are left completely untouched, including their
-- is_active flag and any previously-set rates.
-- ============================================================================

-- ============================================================================
-- Phase F: Update default margin % for FUTURE tenders only. Standard values
-- from the Price List Library sheet's driver cells (STANDARD LABOR MARGIN =
-- 20%, STANDARD MATERIAL MARGIN = 12%). This only changes the column DEFAULT;
-- it does not rewrite any existing tender_register row's stored margin values.
-- ============================================================================
alter table public.tender_register
  alter column default_labor_margin_pct set default 20,
  alter column default_material_margin_pct set default 12;

COMMIT;